#include "controller.hpp"
namespace academy {Controller::Controller(Device&b):board_(b){}void Controller::tick(){if(!board_.input.connected){board_.output.error=true;board_.output.state="disconnected";return;}board_.output.error=false;buffer_+=board_.input.text;std::size_t end;while((end=buffer_.find('\n'))!=std::string::npos){std::string f=buffer_.substr(0,end);buffer_.erase(0,end+1);if(f=="PING")board_.output.outgoing+="PONG\n";else if(f=="LED:1"){board_.output.led=true;board_.output.outgoing+="OK\n";}else if(f=="LED:0"){board_.output.led=false;board_.output.outgoing+="OK\n";}else board_.output.outgoing+="ERR\n";}board_.output.state="uart-ready";}}
